x_comment(x_InferenceDisjunctionFreeELVarsPolicyParameter,"The #$CycInferenceEngine parameter that states the policy for handling the free EL vars in disjunctions. :require-equal means that each disjunct must have the exact same set of EL vars. :compute-intersection means that the intersection of the free EL vars over all disjuncts is taken to be the set of free EL vars for the query. :compute-union means that the union of the free EL vars in all disjuncts is taken to be the set of free EL vars for the query. Default = :require-equal.") :- x_cid(a65b12713d1347).
