x_comment(x_InferenceReturnTypeParameter,"The #$CycInferenceEngine parameter that states what type of thing to return as the result. One of (:answer :bindings :bindings-and-supports :bindings-and-hypothetical-bindings). :answer = list of inference-answer-p, :bindings = binding-lists-p (the default).  Note that (NIL) is returned for a closed query that is proven true, which means that no bindings need be substituted for the query to be true.  :bindings-and-supports = a list of pairs, each of the form (bindings supports), :bindings-and-hypothetical-bindings = a list of length two, the first being the answer bindings and the second being the hypothetical bindings, if any, that were established when hypothesizing the original query used to produce the inference EL query.maximum amount of time in CPU seconds should be spent attempting to answer a query.") :- x_cid(a65b12713d138a).
